INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT145-S2-Q1$batch13$, 145, 2, 1, $batch13$Strengthen$batch13$, $batch13$An electric utility has determined that a new power plant is needed and has decided to build either a natural gas-fired plant or a waste-to-energy plant that would serve as both a trash incinerator and a power plant. Surprisingly, although the waste-to-energy plant would produce roughly three times as much air pollution as the gas-fired plant, environmentalists have come out in unanimous support of this option.$batch13$, $batch13$Which one of the following, if true, most helps to justify the environmentalists’ position?$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=145 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Modern gas-fired power plants produce significantly less pollution than gas-fired power plants that were built several decades ago.$batch13$, $batch13$Weakens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$In the area where the utility operates, both energy use and the volume of trash produced have increased substantially over the last several years.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$The waste-to-energy plant would replace an existing trash incinerator that produces much more air pollution than the waste-to-energy plant would.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Most of the environmentalists believe that air pollution is the area’s most serious environmental problem.$batch13$, $batch13$Weakens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$The vast majority of the air pollution in the area where the utility operates is produced by trucks and automobiles.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$A waste-to-energy plant would produce about three times the air pollution of a gas-fired plant.$batch13$), (1, $batch13$Fact$batch13$, $batch13$Environmentalists unanimously support the waste-to-energy plant.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The answer has to make the dirtier plant the better environmental choice. If it replaced something even dirtier, total pollution would drop.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Show that choosing the waste-to-energy plant reduces pollution overall.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Cleaner modern gas plants make the gas option look better.$batch13$), ($batch13$B$batch13$, $batch13$More energy use and trash show both plants are needed. They don't explain preferring the dirtier one.$batch13$), ($batch13$C$batch13$, $batch13$The new plant replaces an incinerator that pollutes much more, so building it lowers total pollution.$batch13$), ($batch13$D$batch13$, $batch13$If air pollution is their top concern, backing the dirtier plant is even harder to explain.$batch13$), ($batch13$E$batch13$, $batch13$Cars being the main source doesn't make the dirtier plant a better choice.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT145-S2-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
